const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countyFips = '36059'; // FIPS code for Nassau County, New York
  const nassauCounty = ee.FeatureCollection('TIGER/2018/Counties')
    .filter(ee.Filter.eq('GEOID', countyFips))
    .geometry();

  const band = 'tropospheric_NO2_column_number_density';
  const qa_band = 'qa_value';

  const startDay = '10-01';
  const endDay = '10-23';

  const date2021 = ee.Filter.date('2021-' + startDay, '2021-' + endDay);
  const date2019 = ee.Filter.date('2019-' + startDay, '2019-' + endDay);
  const date2018 = ee.Filter.date('2018-' + startDay, '2018-' + endDay);

  // 2. Data Acquisition & Check
  const s5p = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select([band, qa_band])
    .filterBounds(nassauCounty);

  const col2021 = s5p.filter(date2021);
  const col2019 = s5p.filter(date2019);
  const col2018 = s5p.filter(date2018);

  const colBaseline = col2018.merge(col2019);

  const size2021 = col2021.size().getInfo();
  const sizeBaseline = colBaseline.size().getInfo();

  if (size2021 === 0 || sizeBaseline === 0) {
    console.log(`Image count 2021: ${size2021}`);
    console.log(`Image count 2018-2019: ${sizeBaseline}`);
    console.log('No images found for one or both periods.');
    console.log('C1');
    return;
  }
  console.log(`Image count 2021: ${size2021}`);
  console.log(`Image count 2018-2019: ${sizeBaseline}`);

  // 3. Processing: Cloud masking and creating mean composites
  const maskClouds = function(image) {
    // A qa_value > 0.75 is recommended for NO2 to screen for clouds.
    const qa = image.select(qa_band);
    const cloudMask = qa.gte(0.75);
    return image.updateMask(cloudMask);
  };

  const mean2021 = col2021.map(maskClouds).mean().select(band);
  const meanBaseline = colBaseline.map(maskClouds).mean().select(band);

  const scale = 1000; // S5P is coarse, so 1km scale is appropriate

  // 4. Calculation & Validation
  const getStats = function(image, geometry, scale) {
      return image.reduceRegion({
          reducer: ee.Reducer.mean().combine({
              reducer2: ee.Reducer.count(),
              sharedInputs: true
          }),
          geometry: geometry,
          scale: scale,
          maxPixels: 1e9
      });
  };

  const stats2021 = getStats(mean2021, nassauCounty, scale).getInfo();
  const statsBaseline = getStats(meanBaseline, nassauCounty, scale).getInfo();

  const count2021 = stats2021[band + '_count'];
  const countBaseline = statsBaseline[band + '_count'];

  if (!count2021 || !countBaseline || count2021 === 0 || countBaseline === 0) {
      console.log(`Valid pixel count 2021: ${count2021 || 0}`);
      console.log(`Valid pixel count 2018-2019: ${countBaseline || 0}`);
      console.log('No valid pixels after cloud masking.');
      console.log('C2');
      return;
  }

  const val2021 = stats2021[band];
  const valBaseline = statsBaseline[band];

  if (val2021 === null || valBaseline === null) {
      console.log('Calculation resulted in null.');
      console.log('C3');
      return;
  }

  // Units are mol/m^2. Multiply by 1e6 for a more readable micromol/m^2.
  const conversionFactor = 1e6;
  console.log(`2021 valid pixels: ${count2021}`);
  console.log(`2018-2019 valid pixels: ${countBaseline}`);
  console.log(`2021 Mean NO2 (umol/m^2): ${(val2021 * conversionFactor).toFixed(2)}`);
  console.log(`2018-2019 Mean NO2 (umol/m^2): ${(valBaseline * conversionFactor).toFixed(2)}`);

  // 5. Final Answer
  if (val2021 < valBaseline) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  // Handle GEE-specific errors
  if (err.message && (err.message.includes('Collection.loadTable') || err.message.includes('Image.load'))) {
    console.error(`Error: Invalid asset or collection name.`);
    console.log('D');
  } else if (err.message && err.message.includes('computation timed out')) {
    console.error(`Error: Computation timed out. Try increasing the scale.`);
    console.log('D');
  } else {
    console.error(`An unexpected error occurred: ${err.message}`);
    console.log('D');
  }
});
